INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM', 'integrated_science', 9, 'Name the particles of an atom and where they are', ARRAY['INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.a']::text[], 'The child says an atom has protons (positive) and neutrons (no charge) in the nucleus and electrons (negative) in shells around it, and that an atom is neutral because protons and electrons are equal in number. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM', 'integrated_science', 9, 'Work out the mass number from protons and neutrons', ARRAY['INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.b']::text[], 'The child says the mass number is the number of protons plus the number of neutrons, and the atomic number is the number of protons, and works a small sum. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM', 'integrated_science', 9, 'Write the electron arrangement of the first twenty elements', ARRAY['INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.c']::text[], 'The child says the first shell holds up to 2 electrons and the second up to 8, so sodium (11) is 2, 8, 1 and chlorine (17) is 2, 8, 7. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM', 'integrated_science', 9, 'Sort elements into metals and non-metals', ARRAY['INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.d']::text[], 'The child sorts iron, copper, zinc and aluminium as metals and carbon, sulphur, oxygen and chlorine as non-metals, and says metals conduct electricity and shine. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS', 'integrated_science', 9, 'Name the physical properties and uses of metals', ARRAY['INTE.G9.MIXTUR.METALS_AND_ALLOYS.a', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.c']::text[], 'The child says metals are shiny, conduct heat and electricity, can be hammered into sheets (malleable) and drawn into wires (ductile), and are mostly solid, and links copper to wires and aluminium to pots. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS', 'integrated_science', 9, 'Say what alloys are and name common ones', ARRAY['INTE.G9.MIXTUR.METALS_AND_ALLOYS.b', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.c']::text[], 'The child says an alloy is a mixture of a metal with other elements, and names brass (copper and zinc), bronze (copper and tin) and steel (iron and a little carbon), made to be stronger or last longer. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS', 'integrated_science', 9, 'Say what rusting is and how to prevent it', ARRAY['INTE.G9.MIXTUR.METALS_AND_ALLOYS.d']::text[], 'The child says iron rusts when it meets both air (oxygen) and water, and rusting weakens metal, and that painting, oiling, galvanising and plating keep air and water away. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES', 'INTE.G9.MIXTUR.WATER_HARDNESS', 'integrated_science', 9, 'Describe the physical properties of pure water', ARRAY['INTE.G9.MIXTUR.WATER_HARDNESS.a']::text[], 'The child says pure water is colourless, odourless and tasteless, boils at 100 degrees Celsius and freezes at 0 degrees Celsius at sea level, has a density of about 1 g per cm3, expands when it freezes (so ice floats) and dissolves many substances, and uses these to tell pure water from impure water. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT', 'INTE.G9.MIXTUR.WATER_HARDNESS', 'integrated_science', 9, 'Tell hard water from soft water and soften it', ARRAY['INTE.G9.MIXTUR.WATER_HARDNESS.b', 'INTE.G9.MIXTUR.WATER_HARDNESS.c', 'INTE.G9.MIXTUR.WATER_HARDNESS.d']::text[], 'The child says hard water does not lather easily with soap and leaves scum, soft water lathers well, boiling or washing soda can soften it, and hard water leaves scale in kettles. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS', 'integrated_science', 9, 'Name the parts of a leaf and how it suits photosynthesis', ARRAY['INTE.G9.LIVING.NUTRITION_IN_PLANTS.a', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.b']::text[], 'The child names the blade, petiole and veins, the stomata for gas exchange, the chloroplasts with chlorophyll and the palisade layer near the top, and says a broad, thin leaf catches light. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS', 'integrated_science', 9, 'Describe photosynthesis and what it needs', ARRAY['INTE.G9.LIVING.NUTRITION_IN_PLANTS.c', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.d']::text[], 'The child says green plants make glucose from carbon dioxide and water using light and chlorophyll, giving off oxygen, and that iodine turns starch blue-black. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS', 'integrated_science', 9, 'Name modes of nutrition in animals', ARRAY['INTE.G9.LIVING.NUTRITION_IN_ANIMALS.a', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.c']::text[], 'The child names herbivores (plants only), carnivores (flesh only) and omnivores (both), and says animals are grouped by what they eat. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS', 'integrated_science', 9, 'Name the teeth and what each does', ARRAY['INTE.G9.LIVING.NUTRITION_IN_ANIMALS.b']::text[], 'The child says incisors cut, canines tear, premolars and molars grind, and that carnivores have large canines while herbivores have broad molars. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS', 'integrated_science', 9, 'Describe where digestion happens in a human', ARRAY['INTE.G9.LIVING.NUTRITION_IN_ANIMALS.d']::text[], 'The child says digestion starts in the mouth (saliva begins on starch), goes on in the stomach (protein), digested food is absorbed in the small intestine and water is absorbed in the large intestine. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS', 'integrated_science', 9, 'Name the parts of a flower and what they do', ARRAY['INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.a', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.f']::text[], 'The child says sepals protect the bud, petals attract insects, the stamen (anther and filament) is male and the carpel (stigma, style and ovary) is female. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS', 'integrated_science', 9, 'Describe pollination and the adaptations for wind and insects', ARRAY['INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.b', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.c']::text[], 'The child says pollination is the transfer of pollen from an anther to a stigma, wind flowers have feathery stigmas and light pollen, and insect flowers have bright petals, scent and nectar. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS', 'integrated_science', 9, 'Describe fertilisation, fruit formation and seed dispersal', ARRAY['INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.d', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.e']::text[], 'The child says the pollen grows a tube to the ovule, fertilisation makes the ovule a seed and the ovary a fruit, and seeds are dispersed by wind, water, animals or by bursting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L', 'integrated_science', 9, 'Tell biotic from abiotic factors', ARRAY['INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.a']::text[], 'The child says biotic factors are living (plants, animals, microbes) and abiotic factors are non-living (light, temperature, water, soil). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L', 'integrated_science', 9, 'Read food chains and say what human activities do', ARRAY['INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.b', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.c']::text[], 'The child says a food chain starts with a producer (a green plant), then a primary consumer, then a secondary consumer, with arrows pointing to the eater, and that cutting forests and pollution upset food webs. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'INTE.G9.FORCE_.CURVED_MIRRORS', 'integrated_science', 9, 'Name types of curved mirrors and the images they form', ARRAY['INTE.G9.FORCE_.CURVED_MIRRORS.a', 'INTE.G9.FORCE_.CURVED_MIRRORS.c']::text[], 'The child says a concave mirror curves inwards and converges light, a convex mirror curves outwards and spreads it, and that a convex mirror always forms a small, upright, virtual image. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'INTE.G9.FORCE_.CURVED_MIRRORS', 'integrated_science', 9, 'Use the rules of ray diagrams to locate the image in a concave or convex mirror', ARRAY['INTE.G9.FORCE_.CURVED_MIRRORS.b']::text[], 'The child uses two rays from the top of the object (one parallel to the principal axis, reflected through the focus F, or away from it for a convex mirror; one through the centre of curvature C, reflected back on itself) and says where they meet is the image: for a concave mirror with the object beyond C the image is between F and C, real, inverted and smaller; with the object between F and the mirror the image is behind the mirror, virtual, upright and larger; a convex mirror always gives a virtual, upright, smaller image behind it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'INTE.G9.FORCE_.CURVED_MIRRORS', 'integrated_science', 9, 'Say where concave and convex mirrors are used', ARRAY['INTE.G9.FORCE_.CURVED_MIRRORS.d']::text[], 'The child says concave mirrors are used in shaving mirrors, torches and dentist mirrors, and convex mirrors in driving mirrors and shop security mirrors for a wide view. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'INTE.G9.FORCE_.WAVES', 'integrated_science', 9, 'Tell transverse from longitudinal waves', ARRAY['INTE.G9.FORCE_.WAVES.a', 'INTE.G9.FORCE_.WAVES.b']::text[], 'The child says waves are made by vibrations that carry energy, in a transverse wave the particles move at right angles to the direction of travel (water, light), and in a longitudinal wave they move back and forth along it (sound). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'INTE.G9.FORCE_.WAVES', 'integrated_science', 9, 'Name the features of a wave and its uses', ARRAY['INTE.G9.FORCE_.WAVES.c', 'INTE.G9.FORCE_.WAVES.d', 'INTE.G9.FORCE_.WAVES.e']::text[], 'The child names crest, trough, amplitude, wavelength and frequency (waves per second, in hertz), and says remote sensing, radio and ultrasound scans use waves. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'INTE.G8.MIXTUR.ELEMENTS_AND_COMPOUNDS.ATOM_ELEMENT', 'skill', 'essential', 'Grade 8 defined the atom as the smallest particle of an element; Grade 9 opens it up. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
