INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'skill', 'essential', 'The plane-mirror image (Grade 6) is the one curved-mirror images are compared with. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
