INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'SCIE.G6.FORCE_.LIGHT.MIRROR_RULE', 'skill', 'essential', 'Drawing rays and the normal at a mirror was first done in Grade 6. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by an Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'SCIE.G6.FORCE_.LIGHT.MIRROR_IMAGE', 'skill', 'essential', 'Knowing what a plane mirror shows lets the child say why a curved one is chosen instead. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL', 'skill', 'essential', 'Grade 5 showed sound travels through matter by vibrations; Grade 9 names it a longitudinal wave. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'INTE.G8.MIXTUR.PHYSICAL_AND_CHEMICAL_CH.STATES_PARTICLES', 'skill', 'essential', 'How particles move (Grade 8) is what separates the two kinds of wave. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by an Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'INTE.G7.SCIENT.LABORATORY_APPARATUS_AND.SI_BASE', 'skill', 'essential', 'Wavelength in metres and frequency in hertz build on the SI units of Grade 7. Proposed, to confirm by a CBC Integrated Science teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS.M_IS9_AP_ELECTRON', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'Puts the electrons in the nucleus with the protons and neutrons.', '{"question":"Where are electrons found?","wrong_answer":"In the nucleus","correct_answer":"In shells around the nucleus"}'::jsonb, 'Pictures the atom as one solid ball with everything packed in the middle.', 'Offer "In the nucleus" next to the right answer and ask the question again in a new situation.', 'Draw the nucleus as a dot and the shells as rings; place each particle on the drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS.M_IS9_AP_CHARGE', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'Gives the neutron a positive charge, like the proton beside it in the nucleus.', '{"question":"Which particle has no charge?","wrong_answer":"Proton","correct_answer":"Neutron"}'::jsonb, 'Learns the two nucleus particles together and gives them the same charge.', 'Offer "Proton" next to the right answer and ask the question again in a new situation.', 'Link the word: neutron, neutral, no charge.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS.M_IS9_AP_PROTON', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'Gives the proton a negative charge and the electron a positive one.', '{"question":"Which particle is positive?","wrong_answer":"Electron","correct_answer":"Proton"}'::jsonb, 'Swaps the two charged particles because both are learnt in one sentence.', 'Offer "Electron" next to the right answer and ask the question again in a new situation.', 'Proton, positive: both start with P.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER.M_IS9_MN_ADD', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER', 'Subtracts the neutrons from the protons to get the mass number (6 - 6 = 0).', '{"question":"An atom has 6 protons and 6 neutrons. What is the mass number?","wrong_answer":"0","correct_answer":"12"}'::jsonb, 'Has met "neutrons = mass number - atomic number" and uses subtraction the wrong way round.', 'Offer "0" next to the right answer and ask the question again in a new situation.', 'Count the particles in the nucleus: every proton and every neutron adds to the mass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER.M_IS9_MN_ELECTRON', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER', 'Adds the electrons into the mass number.', '{"question":"The mass number counts which particles?","wrong_answer":"Protons and electrons","correct_answer":"Protons and neutrons"}'::jsonb, 'Thinks every particle of the atom must count towards its mass.', 'Offer "Protons and electrons" next to the right answer and ask the question again in a new situation.', 'Electrons are so light that they are left out; the mass is in the nucleus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER.M_IS9_MN_ATOMIC', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER', 'Says the atomic number is the number of neutrons.', '{"question":"The atomic number is the number of...","wrong_answer":"neutrons","correct_answer":"protons"}'::jsonb, 'Mixes the two numbers, which are taught on one line of the table.', 'Offer "neutrons" next to the right answer and ask the question again in a new situation.', 'Atomic number: protons only. Mass number: protons and neutrons.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR.M_IS9_EA_FIRST', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR', 'Puts 8 electrons in the first shell.', '{"question":"How many electrons can the first shell hold?","wrong_answer":"8","correct_answer":"2"}'::jsonb, 'Remembers 8 from the second shell and uses it for every shell.', 'Offer "8" next to the right answer and ask the question again in a new situation.', 'Draw the shells for helium (2) and neon (2, 8) side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR.M_IS9_EA_SODIUM', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR', 'Writes sodium (11 electrons) as 2, 9, putting more than 8 in the second shell.', '{"question":"What is the electron arrangement of sodium (11 electrons)?","wrong_answer":"2, 9","correct_answer":"2, 8, 1"}'::jsonb, 'Fills two shells only and does not open a third when the second is full.', 'Offer "2, 9" next to the right answer and ask the question again in a new situation.', 'Fill shell by shell: 2, then up to 8, then start the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR.M_IS9_EA_SECOND', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR', 'Puts 18 electrons in the second shell.', '{"question":"How many electrons can the second shell hold?","wrong_answer":"18","correct_answer":"8"}'::jsonb, 'Has seen 18 for a later shell in a book and moves it to the second.', 'Offer "18" next to the right answer and ask the question again in a new situation.', 'For the first twenty elements: 2, 8, 8, 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL.M_IS9_MM_CARBON', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL', 'Calls carbon (charcoal, graphite) a metal because graphite is shiny and conducts.', '{"question":"Which is a non-metal?","wrong_answer":"Iron","correct_answer":"Carbon"}'::jsonb, 'Graphite in a pencil is grey and shiny, so it looks like a metal.', 'Offer "Iron" next to the right answer and ask the question again in a new situation.', 'Sort by most properties: carbon is brittle and not malleable, so it is a non-metal (graphite is an odd one that conducts).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL.M_IS9_MM_COPPER', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL', 'Calls copper a non-metal because it is reddish, not silver.', '{"question":"Which is a metal?","wrong_answer":"Sulphur","correct_answer":"Copper"}'::jsonb, 'Expects every metal to be silver-grey.', 'Offer "Sulphur" next to the right answer and ask the question again in a new situation.', 'Test copper wire: it bends, shines and conducts, so it is a metal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL.M_IS9_MM_CONDUCT', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL', 'Says metals are dull and brittle and non-metals conduct electricity.', '{"question":"Which property do metals usually have?","wrong_answer":"They are dull and brittle","correct_answer":"They conduct electricity"}'::jsonb, 'Swaps the two property lists learnt side by side.', 'Offer "They are dull and brittle" next to the right answer and ask the question again in a new situation.', 'Hold a nail and a lump of charcoal in a circuit with a bulb: only the nail lights it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS.M_IS9_AP_ATOM_CHARGED', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ATOM_PARTS', 'Thinks a whole atom has a charge because it has charged particles in it.', '{"question":"An atom has 6 protons and 6 electrons. What is its overall charge?","wrong_answer":"Positive, it has protons","correct_answer":"None: the 6 positive and 6 negative charges cancel"}'::jsonb, 'Counts only one kind of charged particle.', 'Offer "Positive, it has protons" next to the right answer and ask the question again in a new context.', 'Put +6 and -6 counters together: they add to zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER.M_IS9_MN_NEUTRONS_FROM_MASS', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.MASS_NUMBER', 'Finds the number of neutrons by adding the atomic number to the mass number instead of subtracting.', '{"question":"Sodium has mass number 23 and atomic number 11. How many neutrons?","wrong_answer":"34","correct_answer":"12"}'::jsonb, 'Knows both numbers are needed but not which operation.', 'Offer "34" next to the right answer and ask the question again in a new context.', 'Write mass number = protons + neutrons, then cover the neutrons: 23 = 11 + ?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR.M_IS9_EA_SKIP_SHELL', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.ELECTRON_ARR', 'Starts filling the second shell before the first is full, writing hydrogen-like gaps (lithium as 1, 2).', '{"question":"What is the electron arrangement of lithium (3 electrons)?","wrong_answer":"1, 2","correct_answer":"2, 1"}'::jsonb, 'Does not know shells fill from the inside out.', 'Offer "1, 2" next to the right answer and ask the question again in a new context.', 'Fill shells with counters from the nucleus outwards: the first takes 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL.M_IS9_MM_SOLID_IS_METAL', 'INTE.G9.MIXTUR.STRUCTURE_OF_THE_ATOM.METAL_NONMETAL', 'Thinks every solid element is a metal and every gas a non-metal, so sulphur and carbon are metals.', '{"question":"Sulphur is a yellow solid. Is it a metal?","wrong_answer":"Yes, it is a solid","correct_answer":"No: it is dull, brittle and does not conduct, so it is a non-metal"}'::jsonb, 'Sorts by state instead of by properties.', 'Offer "Yes, it is a solid" next to the right answer and ask the question again in a new context.', 'Test a piece of sulphur (picture) against the list of metal properties.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS.M_IS9_MP_MALLEABLE', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS', 'Calls hammering a metal into sheets "ductile".', '{"question":"Which means can be hammered into sheets?","wrong_answer":"Ductile","correct_answer":"Malleable"}'::jsonb, 'Two new words for two similar properties are learnt together.', 'Offer "Ductile" next to the right answer and ask the question again in a new situation.', 'Mabati sheets are made by hammering and rolling: malleable. Wire is drawn: ductile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS.M_IS9_MP_DUCTILE', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS', 'Calls drawing a metal into wires "malleable".', '{"question":"Which means can be drawn into wires?","wrong_answer":"Malleable","correct_answer":"Ductile"}'::jsonb, 'The same pair of words, swapped the other way.', 'Offer "Malleable" next to the right answer and ask the question again in a new situation.', 'Ductile, like a duct or a tube: long and thin, a wire.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS.M_IS9_MP_USE', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS', 'Thinks copper is used for wires because it is cheap or strong, not because it conducts electricity well.', '{"question":"Why is copper used for wires?","wrong_answer":"It does not conduct","correct_answer":"It conducts electricity well"}'::jsonb, 'Gives an everyday reason (price, strength) instead of the property.', 'Offer "It does not conduct" next to the right answer and ask the question again in a new situation.', 'Ask what a wire must do: carry electricity. Then pick the property.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS.M_IS9_AL_MEANING', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS', 'Thinks an alloy is a pure metal, so steel is just iron.', '{"question":"What is an alloy?","wrong_answer":"A pure metal","correct_answer":"A mixture of a metal with other elements"}'::jsonb, 'Steel and brass look like single metals.', 'Offer "A pure metal" next to the right answer and ask the question again in a new situation.', 'Steel is iron with a little carbon; brass is copper with zinc: both are mixtures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS.M_IS9_AL_BRASS', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS', 'Gives copper and tin (bronze) as the metals in brass.', '{"question":"Brass is made of copper and...","wrong_answer":"tin","correct_answer":"zinc"}'::jsonb, 'Mixes brass and bronze, both copper alloys.', 'Offer "tin" next to the right answer and ask the question again in a new situation.', 'Brass: copper and zinc. Bronze: copper and tin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS.M_IS9_AL_STEEL', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS', 'Says steel is iron with copper, not iron with a little carbon.', '{"question":"Steel is iron with a little...","wrong_answer":"copper","correct_answer":"carbon"}'::jsonb, 'Thinks every alloy is two metals.', 'Offer "copper" next to the right answer and ask the question again in a new situation.', 'An alloy can be a metal with a non-metal: steel is iron with carbon.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING.M_IS9_RU_NEED', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING', 'Says iron needs only water to rust, not air too.', '{"question":"What does iron need to rust?","wrong_answer":"Water only","correct_answer":"Air and water"}'::jsonb, 'Sees rust on wet things and links it with water only.', 'Offer "Water only" next to the right answer and ask the question again in a new situation.', 'Set up three nails: in boiled water under oil (no air), in dry air, in air and water. Only the last rusts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING.M_IS9_RU_PREVENT', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING', 'Thinks keeping iron wet or washing it often prevents rusting.', '{"question":"Which prevents rusting?","wrong_answer":"Leaving it wet","correct_answer":"Painting or oiling it"}'::jsonb, 'Thinks cleaning stops all damage.', 'Offer "Leaving it wet" next to the right answer and ask the question again in a new situation.', 'Ask what rust needs; then pick the method that keeps both away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING.M_IS9_RU_EFFECT', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING', 'Says rust is a coat that makes iron stronger.', '{"question":"What does rust do to iron?","wrong_answer":"Makes it stronger","correct_answer":"Weakens it"}'::jsonb, 'Sees rust as a layer like paint.', 'Offer "Makes it stronger" next to the right answer and ask the question again in a new situation.', 'Scrape a rusty nail: the rust flakes off and the nail gets thinner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS.M_IS9_MP_ALL_MAGNETIC', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.METAL_PROPS', 'Thinks a magnet test shows whether something is a metal, so aluminium and copper are not metals.', '{"question":"A magnet does not pick up an aluminium sufuria. Is aluminium a metal?","wrong_answer":"No, a magnet would pick it up","correct_answer":"Yes: it is shiny, conducts and is malleable; only some metals are magnetic"}'::jsonb, 'Uses magnetism as the test for a metal.', 'Offer "No, a magnet would pick it up" next to the right answer and ask the question again in a new context.', 'Test foil for shine, bending and conduction; then with a magnet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS.M_IS9_AL_WEAKER', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.ALLOYS', 'Thinks mixing a metal with another element makes it weaker, so alloys are worse than pure metals.', '{"question":"Why is steel used for building instead of pure iron?","wrong_answer":"It is cheaper but weaker","correct_answer":"It is harder and stronger than pure iron"}'::jsonb, 'Thinks "pure" always means better.', 'Offer "It is cheaper but weaker" next to the right answer and ask the question again in a new context.', 'Compare a soft iron nail bent by hand with a steel spoon that does not bend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING.M_IS9_RU_ALL_METALS', 'INTE.G9.MIXTUR.METALS_AND_ALLOYS.RUSTING', 'Thinks all metals rust, including aluminium and copper.', '{"question":"Does an aluminium sufuria rust?","wrong_answer":"Yes, all metals rust","correct_answer":"No: only iron and steel rust; other metals may corrode in other ways"}'::jsonb, 'Uses "rust" for any damage to a metal.', 'Offer "Yes, all metals rust" next to the right answer and ask the question again in a new context.', 'Compare an old iron nail and an old aluminium pot left outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT.M_IS9_HS_LATHER', 'INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT', 'Says hard water lathers easily with soap.', '{"question":"Which water lathers easily with soap?","wrong_answer":"Hard water","correct_answer":"Soft water"}'::jsonb, 'Thinks "hard" means strong, so it should clean well.', 'Offer "Hard water" next to the right answer and ask the question again in a new situation.', 'Shake soap with rain water and with borehole water: compare the lather.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT.M_IS9_HS_SCALE', 'INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT', 'Says soft water leaves scale in a kettle.', '{"question":"Which leaves scale in a kettle?","wrong_answer":"Soft water","correct_answer":"Hard water"}'::jsonb, 'Swaps the two kinds of water.', 'Offer "Soft water" next to the right answer and ask the question again in a new situation.', 'Look inside a kettle used with borehole water: the white crust comes from hard water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT.M_IS9_HS_SOFTEN', 'INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT', 'Thinks freezing or filtering hard water softens it.', '{"question":"Which can soften hard water?","wrong_answer":"Freezing it","correct_answer":"Boiling it"}'::jsonb, 'Thinks any treatment that cleans water also softens it.', 'Offer "Freezing it" next to the right answer and ask the question again in a new situation.', 'Hardness is dissolved salts: boiling (temporary hardness) or washing soda removes them; filtering does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES.M_IS9_WA_BOIL_ANY', 'INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES', 'Thinks pure water boils at any temperature as long as it bubbles, not at a fixed 100 degrees Celsius at sea level.', '{"question":"At what temperature does pure water boil at sea level?","wrong_answer":"It depends on how big the pot is","correct_answer":"100 degrees Celsius"}'::jsonb, 'Links boiling with bubbles seen, not with a fixed temperature.', 'Offer "It depends on how big the pot is" next to the right answer and ask the question again in a new situation.', 'Boil water in a small and a large pot (teacher) with a thermometer: both read 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES.M_IS9_WA_ICE_HEAVIER', 'INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES', 'Thinks ice is heavier than water, so it should sink.', '{"question":"Why does ice float on water?","wrong_answer":"It does not; ice sinks","correct_answer":"Water expands when it freezes, so ice is less dense than water"}'::jsonb, 'Thinks solids are always heavier than their liquids.', 'Offer "It does not; ice sinks" next to the right answer and ask the question again in a new situation.', 'Put ice in a glass of water; then fill a bottle with water and freeze it: it bulges or cracks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES.M_IS9_WA_PURE_TASTE', 'INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES', 'Thinks pure water has a sweet or fresh taste and a colour.', '{"question":"Which describes pure water?","wrong_answer":"Sweet and slightly blue","correct_answer":"Colourless, odourless and tasteless"}'::jsonb, 'Has tasted spring or borehole water with dissolved minerals.', 'Offer "Sweet and slightly blue" next to the right answer and ask the question again in a new situation.', 'Taste distilled water (from a pharmacy, if safe) beside tap water: distilled tastes of nothing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES.M_IS9_WA_DISSOLVES_NOTHING', 'INTE.G9.MIXTUR.WATER_HARDNESS.WATER_PROPERTIES', 'Thinks water dissolves only sugar and salt, not gases or other substances.', '{"question":"Fish breathe oxygen dissolved in water. Can water dissolve a gas?","wrong_answer":"No, only solids dissolve","correct_answer":"Yes: water dissolves many substances, including gases such as oxygen"}'::jsonb, 'Has seen only solids dissolve in class.', 'Offer "No, only solids dissolve" next to the right answer and ask the question again in a new situation.', 'Open a soda: the gas was dissolved in the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT.M_IS9_HS_HARD_DIRTY', 'INTE.G9.MIXTUR.WATER_HARDNESS.HARD_SOFT', 'Thinks hard water is dirty or unsafe water.', '{"question":"Is hard water unsafe to drink?","wrong_answer":"Yes, it is dirty water","correct_answer":"Not because it is hard: hard water has dissolved calcium and magnesium salts and can be clean and safe"}'::jsonb, 'Thinks "hard" means bad.', 'Offer "Yes, it is dirty water" next to the right answer and ask the question again in a new context.', 'Compare clear borehole water that lathers poorly with muddy rain water that lathers well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS.M_IS9_LP_STOMATA', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS', 'Thinks stomata make sugar, instead of letting gases in and out.', '{"question":"What do stomata do?","wrong_answer":"Make sugar","correct_answer":"Let gases in and out"}'::jsonb, 'Gives every leaf part the leaf''s main job, making food.', 'Offer "Make sugar" next to the right answer and ask the question again in a new situation.', 'Look at a leaf peel under a microscope: stomata are tiny openings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS.M_IS9_LP_CHLORO', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS', 'Puts chlorophyll in the roots.', '{"question":"Where is chlorophyll found?","wrong_answer":"In the roots","correct_answer":"In chloroplasts in leaves"}'::jsonb, 'Thinks the plant takes its food in through its roots.', 'Offer "In the roots" next to the right answer and ask the question again in a new situation.', 'Chlorophyll is green; look for the green parts of the plant.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS.M_IS9_LP_BROAD', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS', 'Says a narrow, thick leaf catches the most light.', '{"question":"Why is a leaf broad and thin?","wrong_answer":"To hide from light","correct_answer":"To catch light and let gases in"}'::jsonb, 'Does not link the shape of the leaf to its job.', 'Offer "To hide from light" next to the right answer and ask the question again in a new situation.', 'Compare a broad banana leaf in shade with a narrow one: more surface catches more light.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS.M_IS9_PS_GAS', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS', 'Says plants take in oxygen to make food.', '{"question":"Which gas is used in photosynthesis?","wrong_answer":"Oxygen","correct_answer":"Carbon dioxide"}'::jsonb, 'Thinks plants breathe like animals and use the same gas for food.', 'Offer "Oxygen" next to the right answer and ask the question again in a new situation.', 'Write the word equation: carbon dioxide + water gives glucose + oxygen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS.M_IS9_PS_PRODUCT', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS', 'Says photosynthesis gives off carbon dioxide.', '{"question":"What does photosynthesis give off?","wrong_answer":"Carbon dioxide","correct_answer":"Oxygen"}'::jsonb, 'Swaps the gas taken in and the gas given off.', 'Offer "Carbon dioxide" next to the right answer and ask the question again in a new situation.', 'Watch bubbles of oxygen rise from a water plant in sunlight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS.M_IS9_PS_TEST', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS', 'Thinks salt water or vinegar, not iodine, tests for starch.', '{"question":"What turns blue-black with starch?","wrong_answer":"Salt water","correct_answer":"Iodine"}'::jsonb, 'Has not done the starch test and guesses a household liquid.', 'Offer "Salt water" next to the right answer and ask the question again in a new situation.', 'Drop iodine on a slice of potato (teacher): it turns blue-black.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS.M_IS9_LP_VEINS_BLOOD', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.LEAF_PARTS', 'Thinks the veins of a leaf carry blood or are only for strength.', '{"question":"What do the veins in a leaf carry?","wrong_answer":"Blood, like ours","correct_answer":"Water and minerals in, and food out to the rest of the plant"}'::jsonb, 'Gives the leaf the body''s parts.', 'Offer "Blood, like ours" next to the right answer and ask the question again in a new context.', 'Stand a white flower or celery in coloured water: the colour travels up the veins.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS.M_IS9_PS_SOIL_FOOD', 'INTE.G9.LIVING.NUTRITION_IN_PLANTS.PHOTOSYNTHESIS', 'Thinks a plant gets its food from the soil, so photosynthesis is not how it feeds.', '{"question":"Where does a maize plant get most of its food from?","wrong_answer":"From the soil through its roots","correct_answer":"It makes it in its leaves by photosynthesis"}'::jsonb, 'Sees roots in the soil as mouths.', 'Offer "From the soil through its roots" next to the right answer and ask the question again in a new context.', 'Weigh soil in a pot before and after a seedling grows for months: it hardly changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION.M_IS9_AN_HERBI', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION', 'Says a herbivore eats flesh.', '{"question":"What does a herbivore eat?","wrong_answer":"Flesh only","correct_answer":"Plants only"}'::jsonb, 'Swaps herbivore and carnivore, learnt as a pair.', 'Offer "Flesh only" next to the right answer and ask the question again in a new situation.', 'Herb is a plant: a herbivore eats plants.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION.M_IS9_AN_CARNI', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION', 'Says a carnivore eats plants.', '{"question":"What does a carnivore eat?","wrong_answer":"Plants only","correct_answer":"Flesh only"}'::jsonb, 'The same pair, swapped the other way.', 'Offer "Plants only" next to the right answer and ask the question again in a new situation.', 'Carne means meat (as in nyama choma): a carnivore eats flesh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION.M_IS9_AN_OMNI', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION', 'Says omnivores eat only plants.', '{"question":"What does an omnivore eat?","wrong_answer":"Plants only","correct_answer":"Plants and animals"}'::jsonb, 'Does not know the word "omni" means all.', 'Offer "Plants only" next to the right answer and ask the question again in a new situation.', 'People eat ugali and meat: we are omnivores.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH.M_IS9_TE_CANINE', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH', 'Gives the incisors the job of tearing flesh.', '{"question":"Which teeth tear flesh?","wrong_answer":"Incisors","correct_answer":"Canines"}'::jsonb, 'The front teeth are the ones the child sees biting.', 'Offer "Incisors" next to the right answer and ask the question again in a new situation.', 'Look at a dog''s long pointed canines: they hold and tear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH.M_IS9_TE_INCISOR', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH', 'Gives the molars the job of cutting food.', '{"question":"Which teeth cut food?","wrong_answer":"Molars","correct_answer":"Incisors"}'::jsonb, 'Thinks the big teeth must do the cutting.', 'Offer "Molars" next to the right answer and ask the question again in a new situation.', 'Bite an apple: the front teeth (incisors) cut it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH.M_IS9_TE_MOLAR', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH', 'Gives the canines the job of grinding food.', '{"question":"Which teeth grind food?","wrong_answer":"Canines","correct_answer":"Molars"}'::jsonb, 'Mixes the names of the back and side teeth.', 'Offer "Canines" next to the right answer and ask the question again in a new situation.', 'Chew maize: the broad back teeth (molars) grind it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION.M_IS9_DG_START', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION', 'Says digestion begins in the stomach, leaving out the mouth.', '{"question":"Where does digestion begin?","wrong_answer":"In the stomach","correct_answer":"In the mouth"}'::jsonb, 'Thinks chewing is only breaking up food, not digesting.', 'Offer "In the stomach" next to the right answer and ask the question again in a new situation.', 'Chew a piece of bread for a long time: it tastes sweet as saliva digests the starch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION.M_IS9_DG_ABSORB', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION', 'Says digested food is absorbed in the stomach or the mouth.', '{"question":"Where is digested food absorbed?","wrong_answer":"In the mouth","correct_answer":"In the small intestine"}'::jsonb, 'Thinks food goes into the body as soon as it is swallowed.', 'Offer "In the mouth" next to the right answer and ask the question again in a new situation.', 'Trace the path on a chart: absorption is in the long small intestine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION.M_IS9_DG_WATER', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION', 'Says most water is absorbed in the oesophagus or the stomach.', '{"question":"Where is most water absorbed?","wrong_answer":"In the oesophagus","correct_answer":"In the large intestine"}'::jsonb, 'Thinks water is taken in where it is first swallowed.', 'Offer "In the oesophagus" next to the right answer and ask the question again in a new situation.', 'Link to Grade 4: the large intestine takes in water, leaving waste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION.M_IS9_AN_ONLY_THREE', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.ANIMAL_NUTRITION', 'Thinks herbivore, carnivore and omnivore are the only modes of nutrition, leaving out parasites (ticks, tapeworms) and saprophytes.', '{"question":"How does a tick get its food from a cow?","wrong_answer":"It is a herbivore","correct_answer":"It is a parasite: it feeds on the living cow''s blood"}'::jsonb, 'Has learnt only the three diet words.', 'Offer "It is a herbivore" next to the right answer and ask the question again in a new context.', 'List animals that feed on others while they live: ticks, fleas, tapeworms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH.M_IS9_TE_ALL_SAME', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.TEETH', 'Thinks all mammals have the same teeth as people, so a goat has big canines like a dog.', '{"question":"Why does a goat have no large canines?","wrong_answer":"It does; all mammals have the same teeth","correct_answer":"It is a herbivore: it needs broad grinding teeth, not tearing canines"}'::jsonb, 'Thinks of teeth as the same in every mammal.', 'Offer "It does; all mammals have the same teeth" next to the right answer and ask the question again in a new context.', 'Compare pictures of a goat skull and a dog skull.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION.M_IS9_DG_STOMACH_ABSORBS_ALL', 'INTE.G9.LIVING.NUTRITION_IN_ANIMALS.DIGESTION', 'Thinks the stomach is where all digestion and absorption happen.', '{"question":"Where is most digestion completed?","wrong_answer":"In the stomach","correct_answer":"In the small intestine"}'::jsonb, 'Feels food "in the stomach" and thinks it all happens there.', 'Offer "In the stomach" next to the right answer and ask the question again in a new context.', 'Trace a meal: mouth (starch begins), stomach (protein begins), small intestine (finished and absorbed).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS.M_IS9_FP_STAMEN', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS', 'Calls the stamen the female part of the flower.', '{"question":"Which part is the male part of a flower?","wrong_answer":"Carpel","correct_answer":"Stamen"}'::jsonb, 'Swaps stamen and carpel, learnt as a pair.', 'Offer "Carpel" next to the right answer and ask the question again in a new situation.', 'The stamen makes pollen, which carries the male cell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS.M_IS9_FP_CARPEL', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS', 'Calls the carpel the male part of the flower.', '{"question":"Which part is the female part of a flower?","wrong_answer":"Stamen","correct_answer":"Carpel"}'::jsonb, 'The same pair, swapped the other way.', 'Offer "Stamen" next to the right answer and ask the question again in a new situation.', 'The carpel holds the ovary with the ovules, which become seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS.M_IS9_FP_PETAL', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS', 'Thinks petals make seeds.', '{"question":"What do petals do?","wrong_answer":"Make seeds","correct_answer":"Attract insects"}'::jsonb, 'Sees petals as the main part of the flower and gives them the main job.', 'Offer "Make seeds" next to the right answer and ask the question again in a new situation.', 'Watch a flower turn into a fruit: the petals fall off; the ovary makes the seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION.M_IS9_PL_MEANING', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION', 'Calls the joining of the male and female cells "pollination".', '{"question":"What is pollination?","wrong_answer":"Joining of male and female cells","correct_answer":"Transfer of pollen to a stigma"}'::jsonb, 'Mixes pollination with fertilisation, which follows it.', 'Offer "Joining of male and female cells" next to the right answer and ask the question again in a new situation.', 'Order the events: pollination (pollen lands), then fertilisation (cells join).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION.M_IS9_PL_WIND', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION', 'Gives wind-pollinated flowers bright petals and nectar.', '{"question":"Which is a feature of a wind-pollinated flower?","wrong_answer":"Bright petals and nectar","correct_answer":"Feathery stigma and light pollen"}'::jsonb, 'Thinks all flowers look like insect flowers.', 'Offer "Bright petals and nectar" next to the right answer and ask the question again in a new situation.', 'Look at a maize tassel and grass flowers: no bright petals, lots of light pollen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION.M_IS9_PL_INSECT', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION', 'Gives insect-pollinated flowers feathery stigmas and light, dusty pollen.', '{"question":"Which is a feature of an insect-pollinated flower?","wrong_answer":"Feathery stigma","correct_answer":"Bright petals and scent"}'::jsonb, 'Swaps the features of the two kinds.', 'Offer "Feathery stigma" next to the right answer and ask the question again in a new situation.', 'Ask what would draw an insect: colour, scent and nectar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL.M_IS9_FD_FRUIT', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL', 'Says the ovule becomes the fruit.', '{"question":"Which part becomes the fruit?","wrong_answer":"The ovule","correct_answer":"The ovary"}'::jsonb, 'Mixes ovule and ovary, which sound alike.', 'Offer "The ovule" next to the right answer and ask the question again in a new situation.', 'Cut a bean pod: the pod was the ovary, the beans were the ovules.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL.M_IS9_FD_SEED', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL', 'Says the ovary becomes the seed.', '{"question":"Which part becomes the seed?","wrong_answer":"The ovary","correct_answer":"The ovule"}'::jsonb, 'The same pair, swapped the other way.', 'Offer "The ovary" next to the right answer and ask the question again in a new situation.', 'One ovary, many ovules: one pod, many beans.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL.M_IS9_FD_WIND', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL', 'Gives wind-dispersed seeds hooks.', '{"question":"Which seeds are carried by wind?","wrong_answer":"Seeds with hooks","correct_answer":"Seeds with wings or hairs"}'::jsonb, 'Mixes the features of animal-dispersed and wind-dispersed seeds.', 'Offer "Seeds with hooks" next to the right answer and ask the question again in a new situation.', 'Hooks catch on fur (blackjack); wings and hairs float on wind (jacaranda, Sodom apple).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS.M_IS9_FP_ONLY_BEAUTY', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FLOWER_PARTS', 'Thinks the only role of flowers in nature is beauty, not reproduction and food for animals.', '{"question":"What is the main role of flowers in a plant''s life?","wrong_answer":"To make the plant beautiful","correct_answer":"To make seeds so new plants grow; they also feed insects and give us fruit"}'::jsonb, 'Sees flowers as decoration, as at weddings.', 'Offer "To make the plant beautiful" next to the right answer and ask the question again in a new context.', 'Follow a bean flower to a pod of seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION.M_IS9_PL_SELF_NEVER', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.POLLINATION', 'Thinks pollen must always come from another plant, so self-pollination is impossible.', '{"question":"Can pollen from a flower land on the stigma of the same flower?","wrong_answer":"No, it must come from another plant","correct_answer":"Yes: that is self-pollination; from another plant is cross-pollination"}'::jsonb, 'Has learnt cross-pollination with bees as the only example.', 'Offer "No, it must come from another plant" next to the right answer and ask the question again in a new context.', 'Show a bean flower, which often pollinates itself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL.M_IS9_FD_WATER_ANY', 'INTE.G9.LIVING.REPRODUCTION_IN_PLANTS.FERTIL_DISPERSAL', 'Thinks any heavy fruit is dispersed by water.', '{"question":"How is a coconut dispersed?","wrong_answer":"By animals, because it is heavy","correct_answer":"By water: its fibrous husk lets it float"}'::jsonb, 'Does not link the feature (a floating husk) with the agent.', 'Offer "By animals, because it is heavy" next to the right answer and ask the question again in a new context.', 'Float a dry coconut husk in a basin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC.M_IS9_BA_LIGHT', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC', 'Calls sunlight a biotic factor because living things need it.', '{"question":"Which is an abiotic factor?","wrong_answer":"A tree","correct_answer":"Sunlight"}'::jsonb, 'Thinks anything that supports life must be living.', 'Offer "A tree" next to the right answer and ask the question again in a new situation.', 'Ask: is it alive? Sunlight does not grow, feed or reproduce.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC.M_IS9_BA_PLANT', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC', 'Calls a plant an abiotic factor because it does not move about.', '{"question":"Which is a biotic factor?","wrong_answer":"Soil","correct_answer":"A plant"}'::jsonb, 'Uses movement as the sign of life.', 'Offer "Soil" next to the right answer and ask the question again in a new situation.', 'Go back to the signs of life from Grade 4: plants grow, reproduce and respond.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC.M_IS9_BA_WATER', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC', 'Calls water biotic because it flows and is found in living things.', '{"question":"Which is an abiotic factor?","wrong_answer":"A frog","correct_answer":"Water"}'::jsonb, 'Thinks moving water is alive.', 'Offer "A frog" next to the right answer and ask the question again in a new situation.', 'Water moves but does not grow, feed or reproduce: it is non-living.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS.M_IS9_FC_START', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS', 'Starts a food chain with an animal, not a green plant.', '{"question":"What does a food chain start with?","wrong_answer":"A herbivore","correct_answer":"A producer"}'::jsonb, 'Thinks the first animal eaten starts the chain.', 'Offer "A herbivore" next to the right answer and ask the question again in a new situation.', 'Ask where the herbivore''s energy came from: a green plant, the producer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS.M_IS9_FC_ARROW', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS', 'Points the arrows from the eater to the eaten (lion to zebra to grass).', '{"question":"In the food chain grass, zebra, lion, which way do the arrows point?","wrong_answer":"From the lion to the zebra to the grass","correct_answer":"From the grass to the zebra to the lion"}'::jsonb, 'Reads the arrow as "eats" pointing at the food.', 'Offer "From the lion to the zebra to the grass" next to the right answer and ask the question again in a new situation.', 'Read each arrow as "is eaten by" or "gives energy to".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS.M_IS9_FC_HUMAN', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS', 'Thinks cutting down a forest affects only the trees, not the animals in the food web.', '{"question":"What does cutting forests do to food webs?","wrong_answer":"Nothing","correct_answer":"Upsets them"}'::jsonb, 'Does not follow the links from the trees to the animals.', 'Offer "Nothing" next to the right answer and ask the question again in a new situation.', 'Follow the web: no trees, no leaves for the herbivores, then no food for the carnivores.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC.M_IS9_BA_DEAD_ABIOTIC_NEVER', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.BIOTIC_ABIOTIC', 'Thinks a dead leaf or a log is abiotic and has nothing to do with living things.', '{"question":"A rotting log in a forest: is it part of the biotic or abiotic environment?","wrong_answer":"Abiotic, it is dead","correct_answer":"It came from a living thing and is food for decomposers such as fungi and termites, so it belongs with the biotic factors"}'::jsonb, 'Uses "alive now" as the only test.', 'Offer "Abiotic, it is dead" next to the right answer and ask the question again in a new context.', 'Look under a rotting log: termites, fungi and beetles live off it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS.M_IS9_FC_REMOVE_NO_EFFECT', 'INTE.G9.LIVING.THE_INTERDEPENDENCE_OF_L.FOOD_CHAINS', 'Thinks removing one animal from a food web affects only the animal that eats it.', '{"question":"Snakes in an area are all killed. What may happen to the number of rats and to the crops?","wrong_answer":"Only the hawks that eat snakes are affected","correct_answer":"Rats may increase and eat more crops"}'::jsonb, 'Follows only one link in the web.', 'Offer "Only the hawks that eat snakes are affected" next to the right answer and ask the question again in a new context.', 'Follow every arrow from and to the snake on the web.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS.M_IS9_CV_CONCAVE', 'INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'Calls a mirror that curves inwards (like a cave) convex.', '{"question":"Which mirror curves inwards?","wrong_answer":"Convex","correct_answer":"Concave"}'::jsonb, 'Swaps the two names, learnt as a pair.', 'Offer "Convex" next to the right answer and ask the question again in a new situation.', 'Concave curves in, like the mouth of a cave; look into a shiny spoon''s bowl.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS.M_IS9_CV_CONVEX', 'INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'Calls a mirror that bulges outwards concave.', '{"question":"Which mirror curves outwards?","wrong_answer":"Concave","correct_answer":"Convex"}'::jsonb, 'The same pair, swapped the other way.', 'Offer "Concave" next to the right answer and ask the question again in a new situation.', 'Look at the back of a shiny spoon: it bulges out, convex.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS.M_IS9_CV_IMAGE', 'INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'Says a convex mirror forms a large, real image.', '{"question":"What image does a convex mirror form?","wrong_answer":"Large and real","correct_answer":"Small, upright and virtual"}'::jsonb, 'Thinks every curved mirror magnifies.', 'Offer "Large and real" next to the right answer and ask the question again in a new situation.', 'Look into the back of a spoon: you see yourself small and upright.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES.M_IS9_MU_DRIVING', 'INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'Says driving mirrors are concave.', '{"question":"Which mirror is used as a driving mirror?","wrong_answer":"Concave","correct_answer":"Convex"}'::jsonb, 'Thinks drivers need a bigger image, not a wider view.', 'Offer "Concave" next to the right answer and ask the question again in a new situation.', 'Ask what a driver needs to see behind: as much of the road as possible.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES.M_IS9_MU_SHAVING', 'INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'Says shaving and make-up mirrors are convex.', '{"question":"Which mirror is used for shaving?","wrong_answer":"Convex","correct_answer":"Concave"}'::jsonb, 'Does not link a larger image with a concave mirror used close up.', 'Offer "Convex" next to the right answer and ask the question again in a new situation.', 'Hold a shiny spoon bowl close to your face: the image is bigger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES.M_IS9_MU_SECURITY', 'INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'Says shop security mirrors are concave.', '{"question":"Which mirror gives a wide view in a shop?","wrong_answer":"Concave","correct_answer":"Convex"}'::jsonb, 'Thinks a security mirror must make things look bigger.', 'Offer "Concave" next to the right answer and ask the question again in a new situation.', 'A convex mirror shows a wide area, small: the guard sees the whole shop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS.M_IS9_RD_ONE_RAY', 'INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'Draws only one ray and marks the image where it hits the axis.', '{"question":"How many rays are needed to locate an image in a ray diagram?","wrong_answer":"One","correct_answer":"Two: the image is where they meet"}'::jsonb, 'Thinks one line from the object shows where the image is.', 'Offer "One" next to the right answer and ask the question again in a new situation.', 'Draw one ray: it could cross anywhere; draw a second and see the single meeting point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS.M_IS9_RD_PARALLEL_RULE', 'INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'Reflects the ray parallel to the axis back parallel, not through the focus.', '{"question":"In a concave mirror, a ray parallel to the principal axis is reflected...","wrong_answer":"Back parallel to the axis","correct_answer":"Through the principal focus F"}'::jsonb, 'Uses the plane-mirror habit of bouncing straight back.', 'Offer "Back parallel to the axis" next to the right answer and ask the question again in a new situation.', 'Shine a torch beam parallel onto a shiny spoon bowl: the light gathers at one point, F.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS.M_IS9_RD_CONVEX_REAL', 'INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'Says a convex mirror can form a real image in front of it.', '{"question":"Where is the image formed by a convex mirror?","wrong_answer":"In front of the mirror, real","correct_answer":"Behind the mirror, virtual"}'::jsonb, 'Uses the concave mirror result for both mirrors.', 'Offer "In front of the mirror, real" next to the right answer and ask the question again in a new situation.', 'Draw the reflected rays of a convex mirror: they spread out, so they only seem to meet behind it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS.M_IS9_RD_CLOSE_INVERTED', 'INTE.G9.FORCE_.CURVED_MIRRORS.RAY_DIAGRAMS', 'Says an object very close to a concave mirror (between F and the mirror) gives an inverted, small image.', '{"question":"An object is placed between F and a concave mirror. What is its image like?","wrong_answer":"Inverted and smaller","correct_answer":"Upright, larger and virtual, behind the mirror"}'::jsonb, 'Uses the far-object result for every position.', 'Offer "Inverted and smaller" next to the right answer and ask the question again in a new situation.', 'Hold a spoon bowl very close to your eye and then far away: the image flips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS.M_IS9_CV_CONCAVE_ALWAYS_BIG', 'INTE.G9.FORCE_.CURVED_MIRRORS.CURVED_MIRRORS', 'Thinks a concave mirror always gives a larger, upright image.', '{"question":"You look into a concave make-up mirror from across the room. What image do you see?","wrong_answer":"Larger and upright","correct_answer":"Upside down and smaller (a real image)"}'::jsonb, 'Has used a make-up mirror only close up.', 'Offer "Larger and upright" next to the right answer and ask the question again in a new context.', 'Look into a spoon bowl close up and then at arm''s length.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES.M_IS9_MU_TORCH_CONVEX', 'INTE.G9.FORCE_.CURVED_MIRRORS.MIRROR_USES', 'Says a torch or a car headlamp uses a convex reflector.', '{"question":"What kind of mirror is behind the bulb in a torch?","wrong_answer":"Convex, to spread the light","correct_answer":"Concave: with the bulb at its focus it sends out a parallel beam"}'::jsonb, 'Thinks spreading light out is the goal.', 'Offer "Convex, to spread the light" next to the right answer and ask the question again in a new context.', 'Look into a torch reflector: it curves in like a bowl.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES.M_IS9_WT_SOUND', 'INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'Calls sound a transverse wave.', '{"question":"Which wave is longitudinal?","wrong_answer":"Water wave","correct_answer":"Sound wave"}'::jsonb, 'Draws every wave as an up-and-down line, so thinks all are transverse.', 'Offer "Water wave" next to the right answer and ask the question again in a new situation.', 'Push and pull a slinky spring along its length: the coils bunch and spread like sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES.M_IS9_WT_WATER', 'INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'Calls water waves longitudinal.', '{"question":"Which wave is transverse?","wrong_answer":"Sound wave","correct_answer":"Water wave"}'::jsonb, 'Swaps the two examples learnt together.', 'Offer "Sound wave" next to the right answer and ask the question again in a new situation.', 'Watch a floating leaf on a pond: it bobs up and down while the wave moves along.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES.M_IS9_WT_DIR', 'INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'Says the particles in a transverse wave move along the direction of travel.', '{"question":"In a transverse wave, particles move...","wrong_answer":"Along the direction of travel","correct_answer":"At right angles to the direction of travel"}'::jsonb, 'Thinks the water itself travels with the wave.', 'Offer "Along the direction of travel" next to the right answer and ask the question again in a new situation.', 'Shake a rope up and down: the wave travels along, the rope moves up and down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS.M_IS9_WP_CREST', 'INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'Calls the highest point of a wave the trough.', '{"question":"What is the highest point of a wave?","wrong_answer":"Trough","correct_answer":"Crest"}'::jsonb, 'Swaps the two names.', 'Offer "Trough" next to the right answer and ask the question again in a new situation.', 'A trough holds water for cattle: it is low. The crest is the top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS.M_IS9_WP_FREQ', 'INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'Gives metres, not hertz, as the unit of frequency.', '{"question":"In what unit is frequency measured?","wrong_answer":"Metres","correct_answer":"Hertz"}'::jsonb, 'Mixes frequency with wavelength, which is measured in metres.', 'Offer "Metres" next to the right answer and ask the question again in a new situation.', 'Frequency counts waves per second: per second is hertz. Wavelength is a length: metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS.M_IS9_WP_LENGTH', 'INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'Calls the distance between two crests the amplitude.', '{"question":"What is the distance between two crests?","wrong_answer":"Amplitude","correct_answer":"Wavelength"}'::jsonb, 'Mixes the two distances marked on a wave drawing.', 'Offer "Amplitude" next to the right answer and ask the question again in a new situation.', 'Amplitude is the height from the middle line; wavelength is crest to crest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_TYPES.M_IS9_WT_WATER_TRAVELS', 'INTE.G9.FORCE_.WAVES.WAVE_TYPES', 'Thinks the water itself travels across the pond with a wave.', '{"question":"A leaf floats on a pond as waves pass. What does the leaf do?","wrong_answer":"It is carried to the edge with the wave","correct_answer":"It bobs up and down in about the same place"}'::jsonb, 'Sees the wave move and thinks the water moves with it.', 'Offer "It is carried to the edge with the wave" next to the right answer and ask the question again in a new context.', 'Drop a stone near a floating leaf and watch it bob.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('INTE.G9.FORCE_.WAVES.WAVE_PARTS.M_IS9_WP_AMPLITUDE_SPEED', 'INTE.G9.FORCE_.WAVES.WAVE_PARTS', 'Thinks a wave with a bigger amplitude travels faster.', '{"question":"Two waves in the same rope have different amplitudes. Which travels faster?","wrong_answer":"The one with the bigger amplitude","correct_answer":"They travel at the same speed; amplitude shows the energy, not the speed"}'::jsonb, 'Links "bigger" with "faster".', 'Offer "The one with the bigger amplitude" next to the right answer and ask the question again in a new context.', 'Send a small and a large shake down the same rope: they arrive at the far end together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
